// src/MapDisplay.js
import React from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline } from 'react-leaflet';
import L from 'leaflet';
import './App.css';

export default function MapDisplay({ routeData, defaultCenter, zoom = 13 }) {
  return (
    <MapContainer
      center={defaultCenter}
      zoom={zoom}
      style={{ height: '100%', width: '100%' }}
      dragging
      scrollWheelZoom
      doubleClickZoom
      zoomControl
    >
      <TileLayer
        attribution='&copy; <a href="https://openstreetmap.org">OpenStreetMap</a> contributors'
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />

      {routeData.map((coord, idx) => {
        // Create a small numbered circle icon
        const numberIcon = L.divIcon({
          className: 'number-icon',
          html: `<div class="number-marker">${idx + 1}</div>`,
          iconSize:     [30, 30],
          iconAnchor:   [15, 30], // point of the icon which will correspond to marker's location
          popupAnchor:  [0, -32]
        });

        return (
          <Marker key={idx} position={coord} icon={numberIcon}>
            <Popup>Stop {idx + 1}<br />[{coord[0].toFixed(5)}, {coord[1].toFixed(5)}]</Popup>
          </Marker>
        );
      })}

      {routeData.length > 1 && (
        <Polyline positions={routeData} weight={4} />
      )}
    </MapContainer>
  );
}


